from typing import List
from pydantic import BaseModel, Field
from microsoft.fabric.hls.hds.ai_enrichments.core.models.enrichment.output.enrichment_context import EnrichmentContext
from microsoft.fabric.hls.hds.ai_enrichments.core.models.enrichment.output.enrichment_output import EnrichmentOutput



class EnrichmentResult(BaseModel):
    """
    EnrichmentResult represents the result of an enrichment process.

    Attributes:
        context (Context): The context in which the enrichment was performed.
        outputs (List[EnrichmentOutput]): A list of outputs generated by the enrichment process.
    """
    context: EnrichmentContext = Field(..., description="The context in which the enrichment was performed.")
    outputs: List[EnrichmentOutput] = Field(..., description="A list of outputs generated by the enrichment process.")
    enrichment_generation_id:str= Field(None, description="Enrichment Generation ID")
    enrichment_definition_id:str= Field(None, description="Enrichment Definition ID")
    
    def to_dict(self):
        """
        Converts the EnrichmentResult object to a dictionary representation.

        Returns:
            dict: A dictionary representation of the EnrichmentResult object.
        """
        return {
            "context": self.context.to_dict(),
            "outputs": [output.to_dict() for output in self.outputs],
            "enrichment_generation_id":self.enrichment_generation_id,
            "enrichment_definition_id":self.enrichment_definition_id
        }